import {ordinal,iso,localToday,weekday,addDays,formatDate,normalize,exclusions,dayKind,calculate,monthBefore,milestone,MIN_DATE,MAX_DATE} from './countdown.js';
const $=s=>document.querySelector(s), $$=s=>[...document.querySelectorAll(s)];
const KEY='hello-someday.settings.v1', SEEN='hello-someday.celebrations.v1';
const weekdays=['Sunday','Monday','Tuesday','Wednesday','Thursday','Friday','Saturday'];
const escape=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let settings=null, current=null, view='countdown', calendarMonth=localToday().slice(0,7), quoteOffset=0, toastTimer, confettiTimer, installPrompt, seen={}, milestoneCheckQueued=false;
const quotes=['Soon, your only meeting will be with the morning sun.','You’ve earned a life with a little less hurry.','The best things ahead won’t need a calendar invite.','A new chapter. A slower coffee. A very happy you.','Less “back to work.” More “where to next?”','Your next great adventure has excellent timing.','Every day is one day closer to time that’s truly yours.','One day, Monday will just be another lovely day.','Here’s to all the things you’ll finally have time for.','You’re not winding down. You’re opening things up.'];
function storageNotice(message){const n=$('#storage-warning');n.textContent=message;n.hidden=false;}
try{const raw=localStorage.getItem(KEY);if(raw)settings=normalize(JSON.parse(raw));seen=JSON.parse(localStorage.getItem(SEEN)||'{}');if(!seen||typeof seen!=='object')seen={};}catch{storageNotice('Saved settings could not be loaded. You can start a new countdown or restore a backup in About.');}
function save(next){settings=normalize(next);try{localStorage.setItem(KEY,JSON.stringify(settings));$('#storage-warning').hidden=true;}catch{storageNotice('This browser isn’t saving data right now. Your countdown works for this visit; export a backup from About before closing.');}render();scheduleMilestone();}
function toast(message,undo){clearTimeout(toastTimer);const t=$('#toast');t.replaceChildren(document.createTextNode(message));if(undo){const b=document.createElement('button');b.textContent='Undo';b.onclick=()=>{undo();t.hidden=true;};t.append(b);}t.hidden=false;toastTimer=setTimeout(()=>t.hidden=true,undo?10000:4500);}
function openDialog(id){const d=$(id);if(!d.open)d.showModal();}
$$('[data-close]').forEach(b=>b.addEventListener('click',()=>b.closest('dialog').close()));
$$('dialog').forEach(d=>d.addEventListener('close',scheduleMilestone));
$$('dialog').forEach(d=>d.addEventListener('click',e=>{if(e.target===d){const r=d.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)d.close();}}));
function setView(next){view=next;$$('[data-view]').forEach(b=>{const active=b.dataset.view===view;b.classList.toggle('active',active);if(active)b.setAttribute('aria-current','page');else b.removeAttribute('aria-current');});$$('.view-panel').forEach(p=>p.hidden=p.id!==`view-${view}`);if(view==='calendar')renderCalendar();if(view==='timeoff')renderTimeOff();}
$$('[data-view]').forEach(b=>b.onclick=()=>setView(b.dataset.view));
function render(){
  $('#welcome').hidden=!!settings;$('#app').hidden=!settings;if(!settings)return;
  current=calculate(settings);const c=current;
  $('#greeting').textContent=settings.name?`${settings.name.toUpperCase()}’S NEXT CHAPTER`:'YOUR NEXT CHAPTER';
  $('#page-title').textContent=c.status==='retired'?'Welcome to your someday.':c.status==='last-day'?'The day you’ve been waiting for.':'A little closer, every day.';
  $('#today-label').textContent=formatDate(c.today,{weekday:'long',year:undefined});
  $('#days-number').textContent=c.remaining.toLocaleString();$('#days-number').dataset.digits=String(c.remaining).length;
  $('#days-label').textContent=c.status==='retired'?'working days. All yours now.':c.status==='coasting'?'working days. Enjoy the runway.':c.remaining===1?'working day to go':'working days to go';
  $('#hero-kicker').textContent=c.status==='last-day'?'IT’S YOUR LAST WORKING DAY':c.status==='retired'?'HELLO, RETIREMENT':'THE COUNTDOWN IS ON';
  $('#count-rule').textContent=c.status==='retired'?'The countdown is complete. The possibilities aren’t.':`${settings.includeToday?'Includes today if scheduled':'Starts tomorrow; today excluded'}. Holidays, PTO and non-workdays are already taken out.`;
  $('#target-label').textContent=settings.dateMeaning==='first-retired'?'FIRST DAY OF RETIREMENT':'YOUR CHOSEN LAST DAY';
  $('#target-date').textContent=formatDate(settings.retirementDate,{weekday:'short'});
  $('#calendar-count').textContent=c.calendarDays.toLocaleString();$('#off-count').textContent=(c.counts.holiday+c.counts.pto).toLocaleString();$('#weekend-count').textContent=c.counts.weekend.toLocaleString();
  $('#last-day').textContent=c.lastWorking?formatDate(c.lastWorking):'No scheduled workday';
  $('#progress-percent').textContent=`${c.percent}%`;$('#progress').value=c.percent;
  $('#progress-caption').textContent=`${c.completed.toLocaleString()} of ${c.total.toLocaleString()} workdays behind you since ${formatDate(settings.startedOn,{year:undefined})}. Updates when your plan changes.`;
  renderQuote();renderMilestones();if(view==='calendar')renderCalendar();if(view==='timeoff')renderTimeOff();
}
function renderQuote(){if(!current)return;$('#quote').textContent=`“${quotes[(ordinal(current.today)+quoteOffset)%quotes.length]}”`;}
$('#next-quote').onclick=()=>{quoteOffset++;renderQuote();};
function renderMilestones(){const c=current;const points=[{day:monthBefore(c.end),title:'One month to go',icon:'☼'},{day:c.end-7,title:'One week to go',icon:'✦'},{day:c.lastWorking?ordinal(c.lastWorking):c.end-1,title:'The final workday',icon:'⚑'},{day:c.end,title:'Hello, retirement',icon:'♡'}];$('#milestone-track').innerHTML=points.map(p=>`<div class="milestone ${ordinal(c.today)>=p.day?'passed':''}"><span class="milestone-icon" aria-hidden="true">${ordinal(c.today)>p.day?'✓':p.icon}</span><h3>${p.title}</h3><p>${formatDate(iso(p.day),{year:undefined})}${ordinal(c.today)===p.day?' · Today!':''}</p></div>`).join('');}
function openSettings(){const s=settings;$('#settings-title').textContent=s?'A little change of plans?':'Your someday starts here.';$('#person-name').value=s?.name||'';$('#retirement-date').value=s?.retirementDate||'';$('#date-meaning').value=s?.dateMeaning||'first-retired';$('#include-today').checked=s?.includeToday!==false;$('#save-settings').textContent=s?'Save my countdown ↗':'Let the countdown begin ↗';$('#settings-error').textContent='';$('#weekday-picker').innerHTML=[1,2,3,4,5,6,0].map(i=>`<label><input type="checkbox" name="weekday" value="${i}" aria-label="${weekdays[i]}" ${(s?.weekdays||[1,2,3,4,5]).includes(i)?'checked':''}><span>${weekdays[i].slice(0,3)}</span></label>`).join('');openDialog('#settings-dialog');}
$('#settings-button').onclick=openSettings;$('#start-button').onclick=openSettings;$('#edit-date').onclick=openSettings;
$('#settings-form').addEventListener('submit',e=>{e.preventDefault();try{const next=normalize({...settings,name:$('#person-name').value,retirementDate:$('#retirement-date').value,dateMeaning:$('#date-meaning').value,includeToday:$('#include-today').checked,weekdays:$$('input[name=weekday]:checked').map(b=>Number(b.value)),daysOff:settings?.daysOff||[],startedOn:settings?.startedOn||localToday()});save(next);$('#settings-dialog').close();toast('Your next chapter is on the calendar.');}catch(err){$('#settings-error').textContent=err.message;}});
function openTimeOff(date=localToday(),entry=null){if(!settings){openSettings();return;}$('#off-id').value=entry?.id||'';$('#off-type').value=entry?.type||'pto';$('#off-label').value=entry?.label||'';$('#off-start').value=entry?.start||date;$('#off-end').value=entry?.end||'';$('#off-error').textContent='';$('#timeoff-title').textContent=entry?'A little change of plans?':'Take a little time for you.';openDialog('#timeoff-dialog');}
$('#add-timeoff').onclick=()=>openTimeOff();
$('#timeoff-form').addEventListener('submit',e=>{e.preventDefault();try{const id=$('#off-id').value||crypto.randomUUID(),entry={id,type:$('#off-type').value,label:$('#off-label').value.trim(),start:$('#off-start').value,end:$('#off-end').value||$('#off-start').value};const daysOff=[...settings.daysOff.filter(x=>x.id!==id),entry];const next=normalize({...settings,daysOff});save(next);$('#timeoff-dialog').close();toast('A little breathing room, saved.');}catch(err){$('#off-error').textContent=err.message;}});
function renderTimeOff(){const list=$('#timeoff-list');if(!settings.daysOff.length){list.innerHTML='<div class="empty-state"><span aria-hidden="true">☼</span><h3>More room for the good stuff.</h3><p>Add your holidays, vacation days or a long weekend. We’ll take them out of your countdown.</p><button class="button secondary small" id="first-timeoff">Add your first day off ↗</button></div>';$('#first-timeoff').onclick=()=>openTimeOff();return;}list.innerHTML=[...settings.daysOff].sort((a,b)=>a.start.localeCompare(b.start)).map(r=>`<div class="off-item ${r.type}"><span class="off-symbol" aria-hidden="true">${r.type==='holiday'?'☼':'✦'}</span><div class="off-info"><h3>${escape(r.label)}</h3><p>${r.type==='holiday'?'Holiday':'PTO'} · ${formatDate(r.start)}${r.end!==r.start?` – ${formatDate(r.end)}`:''}</p></div><button class="text-button" data-edit="${escape(r.id)}" aria-label="Edit ${escape(r.label)}">Edit</button><button class="icon-button" data-delete="${escape(r.id)}" aria-label="Remove ${escape(r.label)}">×</button></div>`).join('');$$('[data-edit]').forEach(b=>b.onclick=()=>openTimeOff(null,settings.daysOff.find(x=>x.id===b.dataset.edit)));$$('[data-delete]').forEach(b=>b.onclick=()=>{const entry=settings.daysOff.find(x=>x.id===b.dataset.delete);save({...settings,daysOff:settings.daysOff.filter(x=>x.id!==entry.id)});toast('Time off removed.',()=>save({...settings,daysOff:[...settings.daysOff,entry]}));});}
function renderCalendar(){if(!settings)return;const first=ordinal(calendarMonth+'-01'),d=new Date(first*86400000);const next=Date.UTC(d.getUTCFullYear(),d.getUTCMonth()+1,1)/86400000;$('#month-title').textContent=formatDate(iso(first),{month:'long',day:undefined});const ranges=exclusions(settings),now=ordinal(localToday());const cells=[1,2,3,4,5,6,0].map(i=>`<span class="weekday-name" aria-label="${weekdays[i]}">${weekdays[i].slice(0,3)}</span>`);for(let i=0;i<(weekday(first)+6)%7;i++)cells.push('<span></span>');for(let day=first;day<next;day++){const date=iso(day),kind=day>=current.end?'retired':dayKind(day,settings,ranges);const entries=ranges.filter(r=>r.from<=day&&r.to>=day);const tag=day===current.end?'Retired!':date===current.lastWorking?'Last day':kind==='holiday'?'Holiday':kind==='pto'?'PTO':kind==='work'?'Work':'';const label=`${formatDate(date,{weekday:'long'})}, ${kind==='weekend'?'non-working day':kind}${entries.length?', '+entries.map(r=>r.label).join(', '):''}${day===now?', today':''}. Add time off`;cells.push(`<button class="calendar-day ${kind} ${day===now?'today':''} ${day<now?'past':''}" data-date="${date}" aria-label="${escape(label)}" ${day===now?'aria-current="date"':''}><span>${Number(date.slice(-2))}</span><small>${tag}</small></button>`);}$('#calendar-grid').innerHTML=cells.join('');$$('[data-date]').forEach(b=>b.onclick=()=>openTimeOff(b.dataset.date));$('#prev-month').disabled=calendarMonth<='1900-01';$('#next-month').disabled=calendarMonth>='2199-12';}
function moveMonth(offset){const [y,m]=calendarMonth.split('-').map(Number);calendarMonth=new Date(Date.UTC(y,m-1+offset,1)).toISOString().slice(0,7);renderCalendar();}
$('#prev-month').onclick=()=>moveMonth(-1);$('#next-month').onclick=()=>moveMonth(1);$('#this-month').onclick=()=>{calendarMonth=localToday().slice(0,7);renderCalendar();};
function clearConfetti(){const layer=$('#confetti');layer.replaceChildren();if(typeof layer.hidePopover==='function' && layer.hasAttribute('popover'))layer.hidePopover();}
function celebrate(event,preview=false){$('#celebration-kicker').textContent=preview?'A SNEAK PEEK OF THE BIG DAY':'A MOMENT WORTH CELEBRATING';$('#celebration-title').textContent=event.title;$('#celebration-message').textContent=event.message;$('#celebration-dialog').classList.toggle('grand',!!event.grand);openDialog('#celebration-dialog');clearTimeout(confettiTimer);clearConfetti();if(matchMedia('(prefers-reduced-motion: reduce)').matches)return;const colors=['#3f7357','#d89b55','#b0be76','#c89baf','#f2d495','#789ab0'];const count=event.grand?170:65;const frag=document.createDocumentFragment();for(let i=0;i<count;i++){const p=document.createElement('i');p.className='confetto';p.style.cssText=`--left:${Math.random()*100}%;--color:${colors[i%colors.length]};--duration:${3+Math.random()*3}s;--delay:${Math.random()*(event.grand?3:1)}s;--drift:${(Math.random()-.5)*260}px;--spin:${(Math.random()-.5)*1800}deg;${i%3===0?'border-radius:50%;width:9px;height:9px;':''}`;frag.append(p);}$('#confetti').append(frag);if(typeof $('#confetti').showPopover==='function'){$('#confetti').setAttribute('popover','manual');$('#confetti').showPopover();}confettiTimer=setTimeout(()=>clearConfetti(),10000);}
$('#celebration-dialog').addEventListener('close',()=>{clearTimeout(confettiTimer);clearConfetti();});
matchMedia('(prefers-reduced-motion: reduce)').addEventListener('change',e=>{if(e.matches)clearConfetti();});
$('#preview-button').onclick=()=>celebrate({title:'You’ve earned your someday.',message:'Imagine this on your last working day. A big, happy hello to everything that’s next.',grand:true},true);
// Coalesce lifecycle changes after forms finish closing. A blocked milestone is
// retried on dialog close or visibility, without consuming its once-only key.
function scheduleMilestone(){if(milestoneCheckQueued)return;milestoneCheckQueued=true;queueMicrotask(()=>{milestoneCheckQueued=false;checkMilestone();});}
function checkMilestone(){
  if(!settings||document.hidden||$$('dialog[open]').length)return;
  current=calculate(settings);const event=milestone(current);if(!event)return;
  const key=`${settings.retirementDate}|${settings.dateMeaning}|${event.key}`;
  try{const saved=JSON.parse(localStorage.getItem(SEEN)||'{}');if(saved&&typeof saved==='object'&&!Array.isArray(saved))seen={...seen,...saved};}catch{}
  if(seen[key])return;
  celebrate(event);
  if(!$('#celebration-dialog').open)return;
  seen[key]=true;try{localStorage.setItem(SEEN,JSON.stringify(seen));}catch{}
}
function showHelp(){openDialog('#help-dialog');$('#export-button').disabled=!settings;}
['#help-button','#install-inline','#privacy-button'].forEach(id=>$(id).onclick=showHelp);
$('#export-button').onclick=()=>{if(!settings)return;const blob=new Blob([JSON.stringify({app:'hello-someday',version:1,settings},null,2)],{type:'application/json'});const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='hello-someday-backup.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('Backup downloaded. Keep it somewhere safe.');};
$('#import-button').onclick=()=>$('#import-file').click();
$('#import-file').onchange=async e=>{const file=e.target.files[0];if(!file)return;try{if(file.size>500000)throw new Error('This file is too large to be a countdown backup.');const data=JSON.parse(await file.text());if(data.app!=='hello-someday'||data.version!==1)throw new Error('Choose a Hello, Someday backup file.');const restored=normalize(data.settings);if(settings&&!confirm('Replace this device’s countdown with the backup?'))return;save(restored);$('#help-dialog').close();toast('Your countdown is restored. Welcome back.');}catch(err){toast(err.message||'The backup could not be restored.');}finally{e.target.value='';}};
window.addEventListener('beforeinstallprompt',e=>{e.preventDefault();installPrompt=e;$('#native-install').hidden=false;});$('#native-install').onclick=async()=>{if(!installPrompt)return;await installPrompt.prompt();installPrompt=null;$('#native-install').hidden=true;};
function connection(){if(!navigator.onLine)$('#connection').textContent='Offline · still counting';else $('#connection').textContent='Made for your next chapter';}window.addEventListener('online',connection);window.addEventListener('offline',connection);connection();
if('serviceWorker' in navigator && (location.protocol==='https:'||['localhost','127.0.0.1'].includes(location.hostname))){navigator.serviceWorker.register('./sw.js').then(()=>navigator.serviceWorker.ready).then(()=>{$('#offline-status').textContent='Ready for offline use. Your countdown and saved settings work without a connection after the first load.';}).catch(()=>{$('#offline-status').textContent='Offline caching is unavailable in this browser. Your settings are still stored locally; reconnect to reopen the app.';});}
let lastToday=localToday();function refreshDay(){const today=localToday();if(today!==lastToday){lastToday=today;quoteOffset=0;render();scheduleMilestone();}}
setInterval(refreshDay,30000);document.addEventListener('visibilitychange',()=>{if(!document.hidden){refreshDay();scheduleMilestone();}});window.addEventListener('pageshow',()=>{refreshDay();scheduleMilestone();});window.addEventListener('storage',e=>{if(e.key===KEY){try{settings=e.newValue?normalize(JSON.parse(e.newValue)):null;render();scheduleMilestone();}catch{storageNotice('A countdown change from another tab could not be read.');}}});
render();scheduleMilestone();
